from itertools import product

# 群元素
elems = ['e','a','h','b','g','z','ep','d']  # alpha=a, eta=h, beta=b, gamma=g, zeta=z, epsilon=ep, delta=d

# 乘法表 (row * col)
# Row e:   e  a  h  b  g  z  ep d
# Row a:   a  h  b  e  z  ep d  g
# Row h:   h  b  e  a  ep d  g  z
# Row b:   b  e  a  h  d  g  z  ep
# Row g:   g  z  ep d  e  a  h  b
# Row z:   z  ep d  g  a  h  b  e
# Row ep:  ep d  g  z  h  b  e  a
# Row d:   d  g  z  ep b  e  a  h

table = {
    'e':  {'e':'e','a':'a','h':'h','b':'b','g':'g','z':'z','ep':'ep','d':'d'},
    'a':  {'e':'a','a':'h','h':'b','b':'e','g':'z','z':'ep','ep':'d','d':'g'},
    'h':  {'e':'h','a':'b','h':'e','b':'a','g':'ep','z':'d','ep':'g','d':'z'},
    'b':  {'e':'b','a':'e','h':'a','b':'h','g':'d','z':'g','ep':'z','d':'ep'},
    'g':  {'e':'g','a':'z','h':'ep','b':'d','g':'e','z':'a','ep':'h','d':'b'},
    'z':  {'e':'z','a':'ep','h':'d','b':'g','g':'a','z':'h','ep':'b','d':'e'},
    'ep': {'e':'ep','a':'d','h':'g','b':'z','g':'h','z':'b','ep':'e','d':'a'},
    'd':  {'e':'d','a':'g','h':'z','b':'ep','g':'b','z':'e','ep':'a','d':'h'},
}

def mul(x, y):
    return table[x][y]

def power(x, n):
    result = 'e'
    for _ in range(n):
        result = mul(result, x)
    return result

def order(x):
    for n in range(1, 9):
        if power(x, n) == 'e':
            return n
    return None

# 1. 计算每个元素的阶
print("=== 元素的阶 ===")
for x in elems:
    print(f"  {x}: order {order(x)}")

# 2. 生成子群
def generate(subset):
    """生成子集的闭包"""
    S = set(subset)
    changed = True
    while changed:
        changed = False
        for x in list(S):
            for y in list(S):
                p = mul(x, y)
                if p not in S:
                    S.add(p)
                    changed = True
    return S

def cyclic_gen(x):
    """生成循环子群 <x>"""
    S = set()
    cur = 'e'
    for _ in range(8):
        S.add(cur)
        cur = mul(cur, x)
        if cur == 'e':
            break
    return S

print("\n=== 循环子群 ===")
for x in elems:
    if x != 'e':
        print(f"  <{x}> = {cyclic_gen(x)}")

# 3. 枚举所有子群：检查所有子集是否为子群
print("\n=== 所有子群（穷举验证）===")
from itertools import combinations

subgroups = []
for size in range(1, 9):
    for subset in combinations(elems, size):
        S = set(subset)
        if 'e' not in S:
            continue
        # 检查封闭性
        is_subgroup = True
        for x in S:
            for y in S:
                if mul(x, y) not in S:
                    is_subgroup = False
                    break
            if not is_subgroup:
                break
        # 检查逆元
        if is_subgroup:
            for x in S:
                found = False
                for y in S:
                    if mul(x, y) == 'e':
                        found = True
                        break
                if not found:
                    is_subgroup = False
                    break
        if is_subgroup:
            subgroups.append(frozenset(S))

# 去重
unique_subgroups = list(set(subgroups))
unique_subgroups.sort(key=lambda s: (len(s), sorted(s)))

for sg in unique_subgroups:
    print(f"  阶 {len(sg)}: {set(sg)}")

print(f"\n共 {len(unique_subgroups)} 个子群")
